/** Test-only producer: one environment whose fixture satisfies one of its two checks. */

import { fileURLToPath } from 'node:url'
import type { Context } from '@deepseek-ai/cordis'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition } from '@deepseek-ai/dsh-environments'
import { CheckId } from '@deepseek-ai/dsh-verification'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    /** A keyless task an implementer with no tools cannot finish; no kind-specific detail. */
    'judge-smoke': Record<string, never>
  }
}

export const name = 'register-environment'
export const inject = ['environments']

const definition: EnvironmentDefinition<'judge-smoke'> = {
  id: EnvironmentId('smoke:blind-judge'),
  kind: 'judge-smoke',
  name: 'smoke:blind-judge',
  description: 'The fixture supplies SPEC.txt; the task also asks for MARKER, which this implementer cannot write.',
  task: {
    prompt: 'The workspace must hold both SPEC.txt and a file named MARKER. Report when it does.',
    fixture: fileURLToPath(new URL('./fixture', import.meta.url)),
  },
  // Both checks only test for a file, so validation leaves the workspace exactly
  // as the attempt's `treeHash` recorded it and the judge's copy reproduces it.
  checks: [
    { id: CheckId('spec-present'), outcome: 'the workspace holds SPEC.txt', run: 'test -f SPEC.txt' },
    { id: CheckId('marker-present'), outcome: 'the workspace holds MARKER', run: 'test -f MARKER' },
  ],
  heldOut: false,
  owner: 'headless-agent blind-judge fixture',
  provenance: 'curated',
  detail: {},
}

/**
 * Register the environment under the producer's own fiber.
 * @param ctx - the plugin context carrying the environment registry.
 */
export function apply(ctx: Context): void {
  ctx.effect(() => ctx.environments.register(definition))
}

/**
 * Keyless adapter serving both routes of the blind-judge scenario: an
 * implementer that reports without changing anything, and a judge that upholds
 * the attempt's recorded outcome. The two are told apart by the provider route
 * alone, which is what proves the judge's turn is a separate model request.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  LlmAdapter,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

/** Provider route the environment runner drives the implementer on. */
export const IMPLEMENTER_PROVIDER = 'implementer-mock'

/** Provider route the judge session is created on. */
export const JUDGE_PROVIDER = 'judge-mock'

/** What the implementer reports without touching the workspace. */
const IMPLEMENTER_REPLY = 'SPEC.txt is already there. I have no tool to write MARKER, so I am reporting instead.'

/** What the judge answers from the evidence alone. */
const JUDGE_REPLY = 'verdict: upheld\nOne of the two checks failed and no certificate was issued, which is the outcome the attempt recorded.'

class BlindJudgeMockAdapter extends LlmAdapter {
  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return { provider, id: model, name: model }
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    yield * reply(options.provider === JUDGE_PROVIDER ? JUDGE_REPLY : IMPLEMENTER_REPLY)
  }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 19, outputTokens: 7 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

export const name = 'judge-mock-llm'
export const inject = ['llm']

/**
 * Register the keyless implementer and judge adapters.
 * @param ctx - the plugin context carrying the LLM runtime.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter([IMPLEMENTER_PROVIDER, JUDGE_PROVIDER], new BlindJudgeMockAdapter())
}

#!/usr/bin/env node
/**
 * Test driver: boot the blind-judge composition, run the registered environment
 * to one uncertified attempt, then audit that attempt through `ctx.judge`.
 *
 * It streams the JUDGE session's canonical events as JSONL — and only that
 * session's, so the transcript a snapshot pins is the record the judge actually
 * read — and ends with one `result` record carrying the judge session's
 * lineage, its derived history, the tools it could see, and the durable verdict
 * read back from the persisted log.
 */

import { mkdir, readdir, readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { Session, SessionEvent, SessionId } from '@deepseek-ai/dsh-session'
import { JUDGE_PROVIDER } from './judge-mock-llm.ts'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('blind-judge driver requires a config path')

// The shipped roster lives beside the installed app; the smoke runs in a
// temporary cwd, so the composition reads the absolute path from here.
process.env.DSH_BLIND_JUDGE_PRESETS ??= fileURLToPath(
  new URL('../../../../../apps/cli/config/agent-presets/', import.meta.url),
)

const ENVIRONMENT = EnvironmentId('smoke:blind-judge')

/** The text blocks of one derived message, joined. */
function messageText(content: readonly { type: string; text?: string }[]): string {
  return content.flatMap(block => (block.type === 'text' && block.text !== undefined ? [block.text] : [])).join('')
}

/** Every persisted session log under the run's store, parsed line by line. */
async function persistedLogs(root: string): Promise<Record<string, unknown>[][]> {
  const files = (await readdir(root, { recursive: true })).filter(file => file.endsWith('.jsonl'))
  return Promise.all(files.map(async file => (await readFile(join(root, file), 'utf8'))
    .split('\n')
    .filter(line => line.trim().length > 0)
    .map(line => JSON.parse(line) as Record<string, unknown>)))
}

const ctx = await boot('blind-judge-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the runner creates its agent only over the settled application.
  await ctx.get('loader')?.await()
  const runner = ctx.get('environmentRuns')
  const judge = ctx.get('judge')
  const environments = ctx.get('environments')
  const tools = ctx.get('tools')
  if (runner === undefined || judge === undefined || environments === undefined || tools === undefined) {
    throw new Error('blind-judge driver requires the runner, the judge, the environment registry, and the tool registry')
  }
  const definition = environments.get(ENVIRONMENT)
  if (definition === undefined) throw new Error('blind-judge driver requires the registered environment')

  const streams = new Map<string, SessionEvent[]>()
  const stopStreaming = ctx.on('session/event', (session: Session, event: SessionEvent) => {
    const events = streams.get(session.id) ?? []
    events.push(event)
    streams.set(session.id, events)
  }, { global: true })
  // Captured while each agent is live: a disposed agent's scope is unwound, so
  // the composed tool view is only readable here.
  const composed = new Map<string, { session: Session; tools: string[] }>()
  const stopComposing = ctx.on('agent/created', ({ agent }: { agent: Agent }) => {
    composed.set(agent.id, { session: agent.session, tools: tools.schemas(agent).map(schema => schema.name).sort() })
  })

  const workspace = join(process.cwd(), 'workspace')
  await mkdir(workspace)
  const report = await runner.run({ environment: ENVIRONMENT, workspace })
  const attempt = report.attempts.at(-1)
  if (attempt === undefined) throw new Error('blind-judge driver requires one recorded attempt')

  const audit = await judge.audit({
    auditedSessionId: report.sessionId,
    attempt: attempt.attempt,
    treeHash: attempt.treeHash,
    workspace,
    taskPrompt: definition.task.prompt,
    results: attempt.results,
    ...report.certificate === undefined ? {} : { certificate: report.certificate },
    model: { provider: JUDGE_PROVIDER, model: JUDGE_PROVIDER },
  })
  stopStreaming()
  stopComposing()

  for (const event of streams.get(audit.judgeSessionId) ?? []) {
    process.stdout.write(`${JSON.stringify({ type: 'session_event', sessionId: audit.judgeSessionId, event })}\n`)
  }

  const judged = composed.get(audit.judgeSessionId)
  if (judged === undefined) throw new Error('blind-judge driver never observed the judge agent')
  const logs = await persistedLogs(join(process.cwd(), '.sessions'))
  const judgeLog = logs.find(records => (records[0] as { id?: string } | undefined)?.id === audit.judgeSessionId) ?? []
  process.stdout.write(`${JSON.stringify({
    type: 'result',
    sessionId: audit.judgeSessionId,
    auditedSessionId: report.sessionId,
    attempt: audit.attempt,
    verdict: audit.verdict,
    rationale: audit.rationale,
    treeHash: audit.treeHash,
    implementerCertified: report.certified,
    implementerResults: attempt.results.map(result => ({ checkId: result.checkId, status: result.status })),
    judgeHeader: {
      hasParent: judged.session.header.parentSession !== undefined,
      seedLength: judged.session.header.seedLength ?? 0,
      agentPreset: judged.session.header.agentPreset ?? null,
    },
    judgeTools: judged.tools,
    judgeHistory: judged.session.deriveMessages().map(message => ({
      role: message.role,
      text: messageText(message.content),
    })),
    durableEvents: judgeLog
      .filter(record => typeof record.type === 'string' && (record.type as string).startsWith('judge/'))
      .map(record => ({ type: record.type, data: record.data })),
    sessionCount: streams.size,
    auditedSessionReachedJudgeLog: judgeLog.some(record => JSON.stringify(record.data ?? {})
      .includes(String(report.sessionId as SessionId))),
  })}\n`)
} finally {
  await ctx.fiber.dispose()
}

import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'
import { DEFAULT_JUDGE_SYSTEM_PROMPT, evidenceText } from '@deepseek-ai/dsh-judge'
import { CheckId } from '@deepseek-ai/dsh-verification'

const fixture = new URL('../../../../examples/headless-agent/tests/fixtures/blind-judge/', import.meta.url)
const binScript = fileURLToPath(new URL('driver.ts', fixture))
const configPath = fileURLToPath(new URL('cordis.yml', fixture))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

interface DriverResult {
  type: string
  sessionId: string
  auditedSessionId: string
  attempt: number
  verdict: string
  rationale: string
  treeHash: string
  implementerCertified: boolean
  implementerResults: { checkId: string; status: string }[]
  judgeHeader: { hasParent: boolean; seedLength: number; agentPreset: string | null }
  judgeTools: string[]
  judgeHistory: { role: string; text: string }[]
  durableEvents: { type: string; data: Record<string, unknown> }[]
  sessionCount: number
  auditedSessionInHistory: boolean
}

const TASK = 'The workspace must hold both SPEC.txt and a file named MARKER. Report when it does.'

describe('the blind judge through a real cordis.yml', () => {
  it('audits one attempt from a lineage-free session holding exactly three messages', async () => {
    const { stdout, stderr } = await runLoaderSmoke({
      label: 'blind-judge',
      tempDirPrefix: 'blind-judge-e2e-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath: repoTsconfig,
    })
    expect(stderr).toBe('')
    const result = JSON.parse(stdout.trimEnd().split('\n').at(-1) ?? '') as DriverResult
    expect(result.type).toBe('result')

    // The attempt under audit: one check passed, one failed, nothing certified.
    expect(result.implementerCertified).toBe(false)
    expect(result.implementerResults).toEqual([
      { checkId: 'spec-present', status: 'pass' },
      { checkId: 'marker-present', status: 'fail' },
    ])

    // The judge session begins at its own creation: a fresh id, no fork parent,
    // and no inherited seed.
    expect(result.sessionId.startsWith('judge-')).toBe(true)
    expect(result.sessionId).not.toBe(result.auditedSessionId)
    expect(result.judgeHeader).toEqual({ hasParent: false, seedLength: 0, agentPreset: null })
    expect(result.sessionCount).toBe(2)

    // Its history is the standing instruction, the task, and the evidence — and
    // nothing from the audited session, whose id no message names.
    expect(result.judgeHistory.map(message => message.role)).toEqual(['user', 'user', 'user', 'assistant'])
    expect(result.judgeHistory.slice(0, 3).map(message => message.text)).toEqual([
      DEFAULT_JUDGE_SYSTEM_PROMPT,
      TASK,
      evidenceText({
        attempt: 1,
        results: [
          { checkId: CheckId('spec-present'), status: 'pass', evidence: '' },
          { checkId: CheckId('marker-present'), status: 'fail', evidence: '' },
        ],
      }),
    ])
    expect(result.auditedSessionInHistory).toBe(false)

    // The shipped `judge` preset composes no tool, and this composition
    // registers none globally, so the judge reaches the model with none.
    expect(result.judgeTools).toEqual([])

    // Both records are durable, and the verdict is the one the judge answered.
    expect(result.verdict).toBe('upheld')
    expect(result.durableEvents).toEqual([
      {
        type: 'judge/session',
        data: {
          judgeSessionId: result.sessionId,
          auditedSessionId: result.auditedSessionId,
          attempt: 1,
          treeHash: result.treeHash,
        },
      },
      {
        type: 'judge/verdict',
        data: {
          auditedSessionId: result.auditedSessionId,
          attempt: 1,
          verdict: 'upheld',
          rationale: result.rationale,
        },
      },
    ])
    expect(result.rationale)
      .toBe('One of the two checks failed and no certificate was issued, which is the outcome the attempt recorded.')
  }, LOADER_SMOKE_TEST_TIMEOUT_MS)
})

